import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastScanner() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1) {
                buffer[0] = -1;
            }
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c <= ' ') {
                c = read();
            }
            boolean neg = (c == '-');
            if (neg) {
                c = read();
            }
            int ret = 0;
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        if (n > 20) {
            System.out.println(0);
            return;
        }
        int[][] p = new int[n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                p[i][j] = fs.nextInt();
            }
        }

        List<Integer> good = new ArrayList<>();
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                for (int k = j + 1; k < n; k++) {
                    if (i == k) continue;
                    if (getAn(p[i], p[j], p[k]) < 90) {
                        continue outer;
                    }
                }
            }
            good.add(i + 1);
        }

        System.out.println(good.size());
        for (int i = 0; i < good.size(); i++) {
            System.out.println(good.get(i));
        }
    }

    static double getAn(int[] p1, int[] p2, int[] p3) {
        double dot = 0, aLen = 0, bLen = 0;
        for (int i = 0; i < p1.length; i++) {
            dot += (p2[i] - p1[i]) * (p3[i] - p1[i]);
            aLen += (p2[i] - p1[i]) * (p2[i] - p1[i]);
            bLen += (p3[i] - p1[i]) * (p3[i] - p1[i]);
        }
        return 180 * Math.acos(dot / Math.sqrt(aLen * bLen)) / Math.PI;
    }
}
